def print_results(results: list[dict]) -> None:
    if not results:
        print("  (no results match the filter)")
        return
    for rank, r in enumerate(results, 1):
        m, c = r["metadata"], r["components"]
        print(f"  #{rank}  score={r['score']:.3f}  {r['doc_id']}  | {r['title']}")
        print(f"       semantic={c['semantic_norm']:.3f} (raw {c['semantic_raw']:.3f})  "
              f"bm25={c['keyword_norm']:.3f} (raw {c['keyword_raw']:.3f})  "
              f"metadata={c['metadata_boost']:.3f}")
        print(f"       meta: category={m.get('category')} date={m.get('date')} "
              f"priority={m.get('priority')} access={m.get('access_level')} "
              f"tags={','.join(m.get('tags', []))}")
        print(f"       {r['content'][:110].strip()}...")


