        {"query": "How do we classify and protect confidential company data?",
         "filters": None, "relevant": ["sec-005"]},
        {"query": "How to request paid time off",
         "filters": None, "relevant": ["hr-002"]},
        {"query": "Database backup and recovery best practices",
         "filters": None, "relevant": ["eng-003"]},
        {"query": "Expense reimbursement for business travel",
         "filters": {"category": "finance"}, "relevant": ["fin-001"]},
        {"query": "Remote work policy and equipment setup for new hires",
         "filters": None, "relevant": ["hr-001", "onb-002"]},
        {"query": "Code review and pull request best practices",
         "filters": {"category": "engineering"}, "relevant": ["eng-001"]},
        {"query": "Vendor contract and procurement requirements",
         "filters": {"category": "finance"}, "relevant": ["fin-003", "fin-002"]},
    ]
    print("--- EVALUATION (P@3, R@3, MRR, NDCG@3)")
    rows, avg = evaluate_retrieval(store, labeled, k=3)
    for row in rows:
        print(f"  {row['query'][:52]:<52} P={row['p@k']:.2f} R={row['r@k']:.2f} "
              f"MRR={row['mrr']:.2f} NDCG={row['ndcg@k']:.2f}  got={row['retrieved']}")
    print("  " + "-" * 70)
    print(f"  {'MACRO AVERAGE':<52} P={avg['p@k']:.2f} R={avg['r@k']:.2f} "
          f"MRR={avg['mrr']:.2f} NDCG={avg['ndcg@k']:.2f}")
    leaked, total, rate = confidential_leakage(store, labeled, k=3)
    print(f"  Confidential leakage in filtered results: {leaked}/{total} "
          f"({rate:.0%}) -> access filters hold")


def run_custom(query: str, k: int, filters, weights=None) -> None:
    store = build_store()
    pipe = RAGPipeline(store)
    out = pipe.answer(query, k=k, filters=filters)
    print(f"Query: {query}")
    if filters:
        print(f"Filters: {json.dumps(filters)}")
    print_results(out["sources"])
    print(f"\nGrounded answer ({out['generator']}):\n  {out['answer']}")


def main(argv: list[str]) -> None:
    if argv:
        query = argv[0]
        k, filters, weights = 4, None, None
        i = 1
        while i < len(argv):
            if argv[i] == "--k" and i + 1 < len(argv):
                k = int(argv[i + 1]); i += 2
            elif argv[i] == "--filter" and i + 1 < len(argv):
                filters = json.loads(argv[i + 1]); i += 2
            elif argv[i] == "--weights" and i + 1 < len(argv):
                weights = json.loads(argv[i + 1]); i += 2
            else:
                i += 1
        run_custom(query, k, filters, weights)
    else:
        run_demo()


if __name__ == "__main__":
    main(sys.argv[1:])

#!/usr/bin/env python3
"""
Metadata-Aware RAG System
=========================
A self-contained Retrieval-Augmented Generation system that:

  * chunks documents and propagates rich metadata to every chunk
  * embeds text locally (TF-IDF over tokens + character n-grams; no external APIs needed)
  * retrieves candidates through a metadata filter engine
    ($eq, $ne, $in, $nin, $gt, $gte, $lt, $lte, $contains, $regex, $exists,
     plus $and / $or / $not combinators)
  * ranks chunks with a hybrid relevance score:
        score = w_semantic * semantic_similarity
              + w_keyword  * BM25 keyword score
              + w_metadata * metadata boost (recency, priority, category match, tag match)
  * supports Maximal Marginal Relevance (diversity) retrieval
  * generates grounded answers (local extractive generator with citations;
    optional OpenAI adapter is used automatically when an API key is present)
  * persists/reloads the index and evaluates retrieval with P@k, R@k, MRR, NDCG
    plus a confidential-leakage metric that verifies access filters hold

Usage:
    Full demo:            python rag_system.py
    Custom query:         python rag_system.py "how do I reset my password" \
                            --k 3 --filter '{"category": "security"}'
"""

from __future__ import annotations

import datetime as _dt
import json
import math
import os
import re
import sys
from collections import Counter

# ----------------------------------------------------------------------------
# Configuration
# ----------------------------------------------------------------------------

REFERENCE_DATE = _dt.date(2025, 3, 1)  # fixed "today" so the demo is reproducible
DATA_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "sample_knowledge_base.json")
INDEX_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "rag_index.json")

DEFAULT_WEIGHTS = {"semantic": 0.45, "keyword": 0.30, "metadata": 0.25}
META_WEIGHTS = {"recency": 0.35, "priority": 0.30, "category": 0.20, "tag": 0.15}

# ----------------------------------------------------------------------------
# Text utilities
# ----------------------------------------------------------------------------

STOPWORDS = set("""
a an and are as at be by for from has he her his i if in is it its of on or
that the they this to was we what when where which who will with you your
how can do does did not but our their them us about into than then so should
would could also may must more most all any each
""".split())

CATEGORY_TERMS = {
    "security": {"password", "mfa", "vpn", "incident", "breach", "security", "authentication",
                 "encryption", "account", "firewall", "okta"},
    "onboarding": {"onboarding", "hire", "equipment", "laptop", "welcome", "checklist", "new"},
    "engineering": {"code", "review", "ci", "cd", "deployment", "api", "database", "backup",
                    "frontend", "performance", "engineering", "pull", "merge", "pipeline",
                    "versioning", "test", "restore"},
    "finance": {"budget", "expense", "reimbursement", "procurement", "vendor", "invoice",
                "finance", "purchase", "contract", "cost", "approval"},
    "hr": {"remote", "time", "pto", "leave", "performance", "review", "hr", "culture",
           "vacation", "sick"},
    "compliance": {"gdpr", "privacy", "soc2", "audit", "compliance", "acceptable", "data",
                   "personal"},
}

PRIORITY_SCALE = {"critical": 5, "high": 4, "medium": 3, "low": 2, "info": 1}


def stem(word: str) -> str:
    w = word.lower()
    if len(w) <= 3:
        return w
    for suffix, repl in (("ing", ""), ("ed", ""), ("ies", "y"), ("es", ""), ("s", "")):
        if w.endswith(suffix) and len(w) - len(suffix) >= 3:
            return w[: len(w) - len(suffix)] + repl
    return w


def tokenize(text: str) -> list[str]:
    return [stem(t) for t in re.findall(r"[a-z0-9']+", text.lower()) if stem(t) not in STOPWORDS]


def char_ngrams(text: str, n: int = 3) -> set[str]:
    grams = set()
    for tok in re.findall(r"[a-z0-9]+", text.lower()):
        if len(tok) >= n + 1:
            for i in range(len(tok) - n + 1):
                grams.add(tok[i : i + n])
    return grams


def sentences(text: str) -> list[str]:
    return [s.strip() for s in re.split(r"(?<=[.!?])\s+", text) if s.strip()]


def _minmax(values: dict) -> dict:
    """Min-max normalize values to [0,1]; neutral 0.5 when all equal."""
    if not values:
        return {}
    lo, hi = min(values.values()), max(values.values())
    if hi == lo:
        return {k: 0.5 for k in values}
    return {k: (v - lo) / (hi - lo) for k, v in values.items()}


# ----------------------------------------------------------------------------
# TF-IDF vectorizer (tokens + character n-grams, cosine similarity)
# ----------------------------------------------------------------------------

class TfidfVectorizer:
    def __init__(self, use_ngrams: bool = True):
        self.use_ngrams = use_ngrams
        self.idf: dict[str, float] = {}

    def _terms(self, text: str) -> list[str]:
        terms = tokenize(text)
        if self.use_ngrams:
            terms = terms + list(char_ngrams(text))
        return terms

    def fit(self, texts: list[str]) -> "TfidfVectorizer":
        n = len(texts)
        df: Counter = Counter()
        for text in texts:
            df.update(set(self._terms(text)))
        self.idf = {t: math.log((n + 1) / (df[t] + 1)) + 1.0 for t in df}
        return self

    def transform(self, text: str) -> dict[str, float]:
        counts = Counter(self._terms(text))
        return {t: (1.0 + math.log(c)) * self.idf[t]
                for t, c in counts.items() if t in self.idf}

    @staticmethod
    def cosine(a: dict[str, float], b: dict[str, float]) -> float:
        if not a or not b:
            return 0.0
        if len(a) > len(b):
            a, b = b, a
        dot = sum(w * b[t] for t, w in a.items() if t in b)
        na = math.sqrt(sum(w * w for w in a.values()))
        nb = math.sqrt(sum(w * w for w in b.values()))
        return dot / (na * nb) if na and nb else 0.0


# ----------------------------------------------------------------------------
# BM25 keyword scorer
# ----------------------------------------------------------------------------

class BM25:
    def __init__(self, k1: float = 1.5, b: float = 0.75):
        self.k1, self.b = k1, b
        self.docs: list[Counter] = []
        self.doc_lens: list[int] = []
        self.avgdl = 1.0
        self.idf: dict[str, float] = {}

    def fit(self, texts: list[str]) -> "BM25":
        self.docs = [Counter(tokenize(t)) for t in texts]
        self.doc_lens = [sum(d.values()) for d in self.docs]
        self.avgdl = sum(self.doc_lens) / len(self.doc_lens) if self.doc_lens else 1.0
        n = len(self.docs)
        df: Counter = Counter()
        for d in self.docs:
            df.update(d.keys())
        self.idf = {t: math.log(1.0 + (n - df[t] + 0.5) / (df[t] + 0.5)) for t in df}
        return self

    def score(self, query: str, doc_idx: int) -> float:
        total = 0.0
        dl = self.doc_lens[doc_idx]
        doc = self.docs[doc_idx]
        for t in set(tokenize(query)):
            w = self.idf.get(t)
            tf = doc.get(t, 0)
            if w and tf:
                denom = tf + self.k1 * (1.0 - self.b + self.b * dl / self.avgdl)
                total += w * (tf * (self.k1 + 1.0)) / denom
        return total


# ----------------------------------------------------------------------------
# Metadata filter engine
# ----------------------------------------------------------------------------

OPERATORS = {"$eq", "$ne", "$in", "$nin", "$gt", "$gte", "$lt", "$lte",
             "$contains", "$regex", "$exists"}


def _compare(op: str, actual, operand) -> bool:
    if op == "$eq":
        return actual == operand
    if op == "$ne":
        return actual != operand
    if op in ("$in", "$nin"):
        values = operand if isinstance(operand, (list, tuple, set)) else [operand]
        hit = actual in values
        return hit if op == "$in" else not hit
    if op == "$contains":
        if actual is None:
            return False
        if isinstance(actual, (list, tuple, set)):
            return operand in actual
        return str(operand) in str(actual)
    if op == "$regex":
        return actual is not None and re.search(str(operand), str(actual)) is not None
    if op == "$exists":
        return bool(operand) == (actual is not None)
    if op in ("$gt", "$gte", "$lt", "$lte"):
        if actual is None:
            return False
        try:
            if isinstance(actual, (int, float)) and isinstance(operand, (int, float)):
                a, b = actual, operand
            else:
                a, b = str(actual), str(operand)  # ISO dates compare lexicographically
        except Exception:
            return False
        return {"$gt": a > b, "$gte": a >= b, "$lt": a < b, "$lte": a <= b}[op]
    return False


def matches_filters(metadata: dict, filters) -> bool:
    """Evaluate a filter dict against chunk metadata.

    Supported forms:
      {"category": "security"}                          exact equality
      {"priority": {"$gte": 4}}                         comparison operators
      {"tags": {"$contains": "mfa"}}                    list membership
      {"access_level": {"$in": ["public", "internal"]}} inclusion
      {"$and": [...], "$or": [...], "$not": {...}}      boolean combinators
    """
    if not filters:
        return True
    for key, cond in filters.items():
        if key == "$and":
            if not all(matches_filters(metadata, f) for f in cond):
                return False
        elif key == "$or":
            if not any(matches_filters(metadata, f) for f in cond):
                return False
        elif key == "$not":
            if matches_filters(metadata, cond):
                return False
        else:
            actual = metadata.get(key)
            if isinstance(cond, dict) and any(op in OPERATORS for op in cond):
                for op, operand in cond.items():
                    if op in OPERATORS and not _compare(op, actual, operand):
                        return False
            elif not _compare("$eq", actual, cond):
                return False
    return True


# ----------------------------------------------------------------------------
# Metadata boost (recency, priority, category match, tag match)
# ----------------------------------------------------------------------------

class MetadataBoost:
    def __init__(self, reference_date: _dt.date):
        self.reference_date = reference_date

    def compute(self, metadata: dict, query_terms: set[str]) -> float:
        rec = self._recency(metadata.get("date"))
        pri = self._priority(metadata.get("priority"))
        cat = self._category(metadata.get("category"), query_terms)
        tag = self._tags(metadata.get("tags"), query_terms)
        return (META_WEIGHTS["recency"] * rec + META_WEIGHTS["priority"] * pri +
                META_WEIGHTS["category"] * cat + META_WEIGHTS["tag"] * tag)

    def _recency(self, value) -> float:
        try:
            d = _dt.date.fromisoformat(str(value))
            days = max(0, (self.reference_date - d).days)
            return max(0.0, min(1.0, 1.0 - days / 365.0))
        except Exception:
            return 0.5

    @staticmethod
    def _priority(value) -> float:
        if isinstance(value, (int, float)):
            return max(0.0, min(1.0, (value - 1) / 4.0))
        if isinstance(value, str):
            return max(0.0, min(1.0, (PRIORITY_SCALE.get(value.lower(), 3) - 1) / 4.0))
        return 0.5

    @staticmethod
    def _category(category, query_terms: set[str]) -> float:
        if category and category in CATEGORY_TERMS and (query_terms & CATEGORY_TERMS[category]):
            return 1.0
        return 0.0

    @staticmethod
    def _tags(tags, query_terms: set[str]) -> float:
        if not tags:
            return 0.0
        tag_terms = set()
        for t in tags:
            tag_terms.update(tokenize(str(t).replace("-", " ")))
        return 1.0 if query_terms & tag_terms else 0.0


# ----------------------------------------------------------------------------
# Document chunking
# ----------------------------------------------------------------------------

def split_document(doc: dict, chunk_size: int, overlap: int) -> list[dict]:
    text = doc["content"]
    base_meta = dict(doc.get("metadata", {}))
    base_meta.setdefault("title", doc.get("title", doc["id"]))
    base_meta["doc_id"] = doc["id"]

    parts: list[tuple[str, int]] = []
    current, current_start, pos = "", 0, 0
    for para in re.split(r"(\n\s*\n)", text):
        if not para.strip():
            pos += len(para)
            continue
        if current and len(current) + len(para) > chunk_size:
            parts.append((current, current_start))
            tail = current[-overlap:] if overlap else ""
            current = ((tail + "\n\n") if tail else "") + para
            current = current.strip()
            current_start = max(0, pos - len(tail))
        else:
            current = (current + ("\n\n" if current else "") + para).strip()
        pos += len(para)
    if current.strip():
        parts.append((current.strip(), current_start))

    chunks = []
    for i, (content, start) in enumerate(parts):
        meta = dict(base_meta)
        meta["chunk_index"] = i
        meta["chunk_count"] = len(parts)
        meta["char_start"] = start
        chunks.append({
            "id": f"{doc['id']}#{i}",
            "doc_id": doc["id"],
            "content": content,
            "metadata": meta,
        })
    return chunks


# ----------------------------------------------------------------------------
# Metadata-aware vector store (filter -> score -> rank)
# ----------------------------------------------------------------------------

class MetadataVectorStore:
    def __init__(self, chunk_size: int = 400, chunk_overlap: int = 60,
                 reference_date: _dt.date | None = None):
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.reference_date = reference_date or _dt.date.today()
        self.chunks: list[dict] = []
        self.doc_index: dict[str, dict] = {}
        self.tfidf = TfidfVectorizer()
        self.bm25 = BM25()

    # ---- indexing ---------------------------------------------------------

    def add_documents(self, documents: list[dict]) -> int:
        for doc in documents:
            for chunk in split_document(doc, self.chunk_size, self.chunk_overlap):
                self.chunks.append(chunk)
                self.doc_index[doc["id"]] = doc.get("metadata", {})
        self._fit()
        return len(self.chunks)

    def _fit(self) -> None:
        contents = [c["content"] for c in self.chunks]
        self.tfidf.fit(contents)
        self.bm25.fit(contents)

    def count(self, filters=None) -> int:
        return sum(1 for c in self.chunks if matches_filters(c["metadata"], filters))

    # ---- retrieval --------------------------------------------------------

    def search(self, query: str, k: int = 5, filters=None,
               weights: dict | None = None) -> list[dict]:
        """Filter -> score (semantic + BM25 + metadata boost) -> rank."""
        weights = weights or DEFAULT_WEIGHTS
        candidate_idx = [i for i, c in enumerate(self.chunks)
                         if matches_filters(c["metadata"], filters)]
        if not candidate_idx:
            return []

        qvec = self.tfidf.transform(query)
        sem_raw = {i: self.tfidf.cosine(qvec, self.tfidf.transform(self.chunks[i]["content"]))
                   for i in candidate_idx}
        bm_raw = {i: self.bm25.score(query, i) for i in candidate_idx}
        sem_norm = _minmax(sem_raw)
        bm_norm = _minmax(bm_raw)
        qterms = set(tokenize(query))
        boost = MetadataBoost(self.reference_date)

        rows = []
        for i in candidate_idx:
            meta = self.chunks[i]["metadata"]
            mb = boost.compute(meta, qterms)
            score = (weights["semantic"] * sem_norm[i] +
                     weights["keyword"] * bm_norm[i] +
                     weights["metadata"] * mb)
            rows.append({
                "chunk_id": self.chunks[i]["id"],
                "doc_id": self.chunks[i]["doc_id"],
                "title": meta.get("title", self.chunks[i]["doc_id"]),
                "content": self.chunks[i]["content"],
                "metadata": meta,
                "score": score,
                "components": {
                    "semantic_raw": sem_raw[i],
                    "semantic_norm": sem_norm[i],
                    "keyword_raw": bm_raw[i],
                    "keyword_norm": bm_norm[i],
                    "metadata_boost": mb,
                },
            })
        rows.sort(key=lambda r: r["score"], reverse=True)
        return rows[:k]

    def mmr_search(self, query: str, k: int = 3, fetch_k: int = 10,
                   lambda_mult: float = 0.6, filters=None,
                   weights: dict | None = None) -> list[dict]:
        """Maximal Marginal Relevance: diversify results while keeping relevance.

        Standard MMR: pick the candidate maximizing
            lambda * sim(query, candidate) - (1 - lambda) * max_{s in selected} sim(candidate, s)
        """
        candidates = self.search(query, k=fetch_k, filters=filters, weights=weights)
        if not candidates:
            return []
        selected: list[dict] = []
        pool = list(candidates)
        while pool and len(selected) < k:
            best, best_val = None, -1e18
            for cand in pool:
                cand_vec = self.tfidf.transform(cand["content"])
                sim_q = cand["components"]["semantic_raw"]
                sim_s = max((self.tfidf.cosine(cand_vec, self.tfidf.transform(s["content"]))
                             for s in selected), default=0.0)
                val = lambda_mult * sim_q - (1.0 - lambda_mult) * sim_s
                if val > best_val:
                    best, best_val = cand, val
            selected.append(best)
            pool.remove(best)
        return selected

    # ---- persistence ------------------------------------------------------

    def save(self, path: str) -> None:
        data = {
            "params": {"chunk_size": self.chunk_size, "chunk_overlap": self.chunk_overlap},
            "reference_date": self.reference_date.isoformat(),
            "doc_index": self.doc_index,
            "chunks": self.chunks,
        }
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, default=str)

    @classmethod
    def load(cls, path: str, reference_date: _dt.date | None = None) -> "MetadataVectorStore":
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
        store = cls(chunk_size=data["params"]["chunk_size"],
                    chunk_overlap=data["params"]["chunk_overlap"],
                    reference_date=reference_date or _dt.date.fromisoformat(data["reference_date"]))
        store.chunks = data["chunks"]
        store.doc_index = data["doc_index"]
        store._fit()
        return store


def doc_level(results: list[dict]) -> list[dict]:
    """Deduplicate chunk-level results to document level (keep best-ranked chunk)."""
    seen, out = set(), []
    for r in results:
        if r["doc_id"] not in seen:
            seen.add(r["doc_id"])
            out.append(r)
    return out


# ----------------------------------------------------------------------------
# RAG pipeline (retrieve -> grounded generation)
# ----------------------------------------------------------------------------

class RAGPipeline:
    def __init__(self, store: MetadataVectorStore, top_k_context: int = 4,
                 max_sentences: int = 6, max_chars: int = 1000,
                 weights: dict | None = None):
        self.store = store
        self.top_k_context = top_k_context
        self.max_sentences = max_sentences
        self.max_chars = max_chars
        self.weights = weights or DEFAULT_WEIGHTS

    def answer(self, query: str, k: int = 4, filters=None) -> dict:
        results = self.store.search(query, k=k, filters=filters, weights=self.weights)
        context = self._build_context(results)
        answer, generator = self._generate(query, results)
        sources = [{
            "rank": i + 1,
            "chunk_id": r["chunk_id"],
            "doc_id": r["doc_id"],
            "title": r["title"],
            "score": round(r["score"], 4),
            "breakdown": {key: round(val, 4) for key, val in r["components"].items()},
            "metadata": {key: r["metadata"].get(key) for key in
                         ("category", "department", "date", "priority", "access_level", "tags", "version")},
        } for i, r in enumerate(results)]
        return {"query": query, "filters": filters, "answer": answer,
                "generator": generator, "context": context, "sources": sources}

    def _build_context(self, results: list[dict]) -> str:
        parts = []
        for rank, r in enumerate(results, start=1):
            m = r["metadata"]
            header = (f"[{rank}] {r['title']} "
                      f"(doc_id={r['doc_id']}, category={m.get('category')}, "
                      f"date={m.get('date')}, priority={m.get('priority')})")
            parts.append(header)
            parts.append(r["content"])
        return "\n\n".join(parts)

    def _generate(self, query: str, results: list[dict]) -> tuple[str, str]:
        context = self._build_context(results)
        llm_answer = self._llm_generate(query, context)
        if llm_answer:
            return llm_answer, "openai"
        return self._extractive_answer(query, results), "extractive"

    def _llm_generate(self, query: str, context: str):
        """Optional adapter: uses OpenAI when the SDK and API key are available."""
        try:
            if not os.environ.get("OPENAI_API_KEY"):
                return None
            from openai import OpenAI
            client = OpenAI()
            system = ("Answer the question using only the provided context. "
                      "If the context does not contain the answer, say so. "
                      "Cite sources as [1], [2], etc.")
            resp = client.chat.completions.create(
                model=os.environ.get("RAG_LLM_MODEL", "gpt-4o-mini"),
                temperature=0,
                messages=[{"role": "system", "content": system},
                          {"role": "user",
                           "content": f"Context:\n{context}\n\nQuestion: {query}"}],
            )
            return resp.choices[0].message.content
        except Exception:
            return None

    def _extractive_answer(self, query: str, results: list[dict]) -> str:
        """Grounded extractive generator: pick query-relevant sentences, cite chunks.

        A sentence is kept only if it shares at least 2 distinct query terms,
        which filters out near-empty overlaps with low-ranked chunks.
        """
        qterms = set(tokenize(query))
        scored = []
        for rank, r in enumerate(results, start=1):
            for sent in sentences(r["content"]):
                sterms = set(tokenize(sent))
                if not sterms:
                    continue
                shared = qterms & sterms
                if len(shared) < 2:
                    continue
                overlap = sum(self.store.tfidf.idf.get(t, 1.0) for t in shared)
                scored.append((overlap, rank, sent))
        if not scored:
            return ("I don't have enough information to answer this query based on "
                    "the retrieved documents.")
        chosen = sorted(scored, key=lambda x: (-x[0], x[1]))[: self.max_sentences]
        chosen = sorted(chosen, key=lambda x: x[1])  # restore narrative order
        seen, lines, total = set(), [], 0
        for _overlap, rank, sent in chosen:
            if sent in seen:
                continue
            seen.add(sent)
            line = f"{sent} [{rank}]"
            if total + len(line) > self.max_chars:
                break
            lines.append(line)
            total += len(line)
        return " ".join(lines)


# ----------------------------------------------------------------------------
# Evaluation (P@k, R@k, MRR, NDCG@k, confidential leakage)
# ----------------------------------------------------------------------------

def evaluate_retrieval(store: MetadataVectorStore, labeled: list[dict],
                       k: int = 3, weights: dict | None = None) -> tuple[list[dict], dict]:
    rows = []
    for item in labeled:
        results = store.search(item["query"], k=k, filters=item.get("filters"), weights=weights)
        ids = [r["doc_id"] for r in doc_level(results)]
        rel_set = set(item["relevant"])
        rel = [1 if i in rel_set else 0 for i in ids]
        p = sum(rel) / k
        r = sum(rel) / len(rel_set) if rel_set else 0.0
        mrr = next((1.0 / pos for pos, flag in enumerate(rel, start=1) if flag), 0.0)
        dcg = sum(flag / math.log2(pos + 1) for pos, flag in enumerate(rel, start=1))
        idcg = sum(1.0 / math.log2(pos + 1) for pos in range(1, min(k, len(rel_set)) + 1))
        ndcg = dcg / idcg if idcg else 0.0
        rows.append({"query": item["query"], "p@k": p, "r@k": r, "mrr": mrr,
                     "ndcg@k": ndcg, "retrieved": ids, "relevant": sorted(rel_set)})
    avg = {m: sum(row[m] for row in rows) / len(rows) for m in ("p@k", "r@k", "mrr", "ndcg@k")}
    return rows, avg


def confidential_leakage(store: MetadataVectorStore, labeled: list[dict],
                         k: int = 3, weights: dict | None = None) -> tuple[int, int, float]:
    """Count how many confidential documents leak into filtered top-k results."""
    leaked = total = 0
    for item in labeled:
        if not item.get("filters"):
            continue
        for r in store.search(item["query"], k=k, filters=item["filters"], weights=weights):
            total += 1
            if r["metadata"].get("access_level") == "confidential":
                leaked += 1
    rate = leaked / total if total else 0.0
    return leaked, total, rate


